/**
 * KinematicBody - Physics body with pathfinding capabilities.
 *
 * Automatically used for BodyType.KINEMATIC bodies.
 * Provides pathfinding methods that communicate with the physics worker.
 */
export class KinematicBody extends Body {
    /**
     * Create a kinematic body with pathfinding support.
     *
     * @param {Object} views - Physics views object containing type-indexed body arrays.
     * @param {string} type - Body type (should be 'kinematic').
     * @param {number} index - Body index in the views array.
     * @param {THREE.Object3D|null} entity - Optional entity to sync transforms to.
     * @param {Object} physics - Physics instance for worker communication.
     */
    constructor(views: any, type: string, index: number, entity: THREE.Object3D | null, physics: any);
    /**
     * Three.js-style type flag. True for KinematicBody instances.
     * @type {boolean}
     * @readonly
     */
    readonly isKinematicBody: boolean;
    _pathfindingEnabled: boolean;
    _pathfindingConfig: {
        maxSpeed: number;
        arrivalRadius: number;
        avoidanceRadius: number;
        replanThreshold: number;
        rotationSpeed: any;
    };
    _agent: Agent;
    _navigation: Navigation;
    /**
     * Camera instance for this body (for spectating/multiplayer).
     * @type {Object|null}
     * @private
     */
    private _camera;
    _navigationState: number;
    _destination: any;
    _navigationPromise: any;
    _navigationResolve: (value: boolean | PromiseLike<boolean>) => void;
    _navigationReject: (reason?: any) => void;
    _pollInterval: number;
    _navigationVersion: number;
    /**
     * Enable pathfinding for this body.
     *
     * @param {Object} [config={}] - Pathfinding configuration.
     * @param {number} [config.maxSpeed=5.0] - Maximum movement speed.
     * @param {number} [config.arrivalRadius=1.5] - Distance to consider arrived.
     * @param {number} [config.avoidanceRadius=1.5] - Obstacle avoidance radius.
     * @param {number} [config.replanThreshold=5.0] - Time blocked before replanning.
     * @returns {Promise<boolean>} Success status.
     */
    enablePathfinding(config?: {
        maxSpeed?: number;
        arrivalRadius?: number;
        avoidanceRadius?: number;
        replanThreshold?: number;
    }): Promise<boolean>;
    /**
     * Navigate to a destination.
     *
     * @param {THREE.Vector3|{x: number, y: number, z: number}} destination - Target position.
     * @param {Function} [onArrived] - Optional callback when arrived.
     * @returns {Promise<boolean>} Resolves true on arrival, false on path failure.
     */
    navigateTo(destination: THREE.Vector3 | {
        x: number;
        y: number;
        z: number;
    }, onArrived?: Function): Promise<boolean>;
    /**
     * Stop current navigation.
     *
     * @returns {Promise<void>}
     */
    stopNavigation(): Promise<void>;
    /**
     * Cancel navigation without stopping in worker (internal).
     *
     * @private
     */
    private _cancelNavigation;
    /**
     * Complete navigation with result.
     *
     * @param {boolean} success - Whether navigation succeeded.
     * @param {Function|null} callback - Optional arrival callback.
     * @private
     */
    private _completeNavigation;
    /**
     * Check if currently navigating.
     *
     * @type {boolean}
     * @readonly
     */
    readonly get isNavigating(): boolean;
    /**
     * Check if navigation was enabled.
     *
     * @type {boolean}
     * @readonly
     */
    readonly get pathfindingEnabled(): boolean;
    /**
     * Get current destination (if navigating).
     *
     * @type {THREE.Vector3|null}
     * @readonly
     */
    readonly get destination(): THREE.Vector3 | null;
    /**
     * Agent configuration interface.
     *
     * Provides immediate sync of pathfinding parameters to the physics worker.
     * Changes to properties are applied instantly without requiring re-initialization.
     *
     * @type {Agent}
     * @readonly
     * @example
     * ```js
     * // Adjust speed during gameplay
     * body.agent.steering.maxSpeed = 10;
     *
     * // Batch configuration
     * body.agent.set({ rotationSpeed: 0.2, maxSpeed: 8 });
     * ```
     */
    readonly get agent(): Agent;
    /**
     * AI agent interface for adding sensors and intents.
     *
     * Provides a Three.js-style API for configuring AI behavior.
     *
     * @type {AIAgent}
     * @readonly
     *
     * @example
     * // Add sensors and intents
     * body.ai.addSensor(new VisionSensor({ fov: 90, range: 30 }));
     * body.ai.addIntent(new PatrolIntent({ waypoints: [...] }));
     * body.ai.addIntent(new EngageIntent({ priority: 80 }));
     * body.ai.enable();
     *
     * // Chaining
     * body.ai
     *   .addSensor(new VisionSensor({ fov: 90 }), new DamageSensor())
     *   .addIntent(new PatrolIntent({ waypoints: [...], priority: 20 }))
     *   .addIntent(new EngageIntent({ priority: 80 }))
     *   .enable();
     */
    readonly get ai(): AIAgent;
    _ai: AIAgent;
    /**
     * Navigation interface for pathfinding.
     *
     * Provides BASIC (straight-line) and A* pathfinding navigation.
     * BASIC mode requires no setup - just call navigateTo().
     * A* mode requires a PathfindingGrid via enable().
     *
     * @type {Navigation}
     * @readonly
     *
     * @example
     * // BASIC mode - no setup required
     * body.navigation.navigateTo(targetPosition);
     *
     * // A* mode with PathfindingGrid
     * await body.navigation.enable(grid, { maxSpeed: 5 });
     * body.navigation.navigateTo(targetPosition);
     *
     * // Check state
     * if (body.navigation.isNavigating) { ... }
     *
     * // Stop navigation
     * body.navigation.stop();
     */
    readonly get navigation(): Navigation;
    /**
     * Alias for navigation (backwards compatibility).
     * @type {Navigation}
     * @readonly
     * @deprecated Use navigation instead
     */
    readonly get pathfinder(): Navigation;
    /**
     * Set camera instance for this body.
     *
     * @param {Object|null} cam - Camera instance
     */
    set camera(cam: any | null);
    /**
     * Get camera instance for this body.
     * Used for spectating and multiplayer scenarios.
     *
     * @returns {Object|null} Camera instance or null
     */
    get camera(): any | null;
    /**
     * Disable pathfinding and clean up.
     *
     * @returns {Promise<void>}
     */
    disablePathfinding(): Promise<void>;
}
export default KinematicBody;
import { Body } from './Body.js';
import { Agent } from './Agent.js';
import { Navigation } from '../navigation/Navigation.js';
import { AIAgent } from '../ai/AIAgent.js';
